function main(req) {
  if (req.method !== 'POST') {
    return { error: 'POST required', status: 405 };
  }

  const body = jsonParse(req.body, {});

  // Validate required fields
  const errors = [];
  if (!body.name || body.name.trim().length < 2) errors.push('name is required (min 2 chars)');
  if (!body.email || !/^[^@]+@[^@]+\.[^@]+$/.test(body.email)) errors.push('valid email is required');
  if (!body.message || body.message.trim().length < 10) errors.push('message is required (min 10 chars)');

  if (errors.length > 0) {
    return { success: false, errors };
  }

  // Sanitize input
  const sanitized = {
    name: body.name.trim().substring(0, 100),
    email: body.email.trim().toLowerCase().substring(0, 255),
    message: body.message.trim().substring(0, 2000),
    submitted_at: new Date().toISOString(),
    id: uuid()
  };

  log('form submission:', sanitized.id, sanitized.email);

  return {
    success: true,
    submission: sanitized,
    message: 'Thank you for your submission'
  };
}
